            bottom = max(r for r, c in cells)
            left = min(c for r, c in cells)
            right = max(c for r, c in cells)
            enclosed = {}
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    color = grid[r][c]
                    if color and color != main:
                        enclosed.setdefault(color, []).append((r, c))
            if not enclosed:
                continue
            sec = max(enclosed, key=lambda color: len(enclosed[color]))
            points = enclosed[sec]
            for r, c in points:
                out[r][c] = 0
            dr = (top + bottom) / 2 - sum(r for r, c in points) / len(points)
            dc = (left + right) / 2 - sum(c for r, c in points) / len(points)
            if abs(dr) >= abs(dc):
                if dr > 0:
                    tips = [(r, c) for r, c in cells if r == top]
                    c = round(sum(c for r, c in tips) / len(tips))
                    for rr in range(top):
                        out[rr][c] = sec
                else:
                    tips = [(r, c) for r, c in cells if r == bottom]
                    c = round(sum(c for r, c in tips) / len(tips))
                    for rr in range(bottom + 1, h):
                        out[rr][c] = sec
            elif dc > 0:
                tips = [(r, c) for r, c in cells if c == left]
                r = round(sum(r for r, c in tips) / len(tips))
                for cc in range(left):
                    out[r][cc] = sec
            else:
                tips = [(r, c) for r, c in cells if c == right]
                r = round(sum(r for r, c in tips) / len(tips))
                for cc in range(right + 1, w):
                    out[r][cc] = sec
    return out
